\pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa195\itap0 {\field{\*\fldinst HYPERLINK "hida://5060[0].5064/?u"}{\fldrslt \plain \f2\lang1033\fs22\chcbpat17 Einband aus dem Jahr der Restaurierung}}\plain \f2\lang1033\fs22 : {\field{\*\fldinst HYPERLINK "hida://5260[0]/?u"}{\fldrslt \plain \f2\lang1033\fs22\chcbpat17 Holzdeckel mit hellbraunem Schweinsleder\u252 \'fcberzug}}\plain \f2\lang1033\fs22  und Streicheisenlinien (gleicht Mss. D 1, D 3 und D 4); Spiegel neu; Lektionarfragmente (15. Jh.) des alten Einbands jetzt unter K 13: 002. Ausf\u252 \'fchrlicher zu den Fragmenten und Neubindung des Bandes in D\u252 \'fcsseldorf nach 1819/20 vgl. Karpp, B\u252 \'fccherbesitz Essen, S. 83\endash 89; Ders., Hss. Stift Essen, S. 185\endash 189.}

