\pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa195\itap0 \plain \f2\lang1033\fs22 206v\endash 209r {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f2\scaps\lang1033\fs22\chcbpat17 Missae diversae cum lectionibus}}\plain \f2\i\lang1033\fs24  (206v) \plain \f2\i\lang1033\fs22 De inventione corporis sancti Stephani\plain \f2\i\lang1033\fs24  \plain \f2\i\lang1033\fs22 Deus qui es sanctorum tuorum splendor mirabilis quique hodierna die martirum tuorum Stephani, Nichodemi, Gamalielis atque Abibonis\u8230 \'85\plain \f2\lang1033\fs22  vgl. CO Nr. 1596; \plain \f2\i\lang1033\fs22 Transfigvratio Christi in monte Thabor \plain \f2\lang1033\fs22 CO Nr. 1674; (207r) \plain \f2\i\lang1033\fs22 Lectio libri apocalipsis Iohannis apostoli\plain \f2\lang1033\fs22  (Apo 1,12\endash 18); \plain \f2\i\lang1033\fs22 Secundvm Marcvm \plain \f2\lang1033\fs22 (Mc 9,1\endash 8); (207v) \plain \f2\i\lang1033\fs22 Evangelium secundum Lvcam\plain \f2\lang1033\fs22  (Lc 10,1\endash 7); (208r) >\plain \f2\i\lang1033\fs22 Natale sanctae Margarete\plain \f2\lang1033\fs22 < CO Nr. 1384a; >\plain \f2\i\lang1033\fs22 X kalendas augustas natale sancti Liborii<. Omnipotens sempiterne deus qui ecclesiam tuam in sancti tui nominis confessione solidasti presta quaesumus\plain \f2\lang1033\fs22 \u8230 \'85 vgl. Vry (1997), S. 16ff.; (208v) >\plain \f2\i\lang1033\fs22 XI kalendas augustas natale sancti Arbogasti\plain \f2\lang1033\fs22 <. \plain \f2\i\lang1033\fs22 Deus qui nos annua beati Arbogasti\u8230 \'85\plain \f2\lang1033\fs22 ;\plain \f2\i\lang1033\fs22 >VIII kalendas avgustas\plain \f2\lang1033\fs22  \plain \f2\i\lang1033\fs22 natale sancti Cristophori\plain \f2\lang1033\fs22 <. \plain \f2\i\lang1033\fs22 Deus qui nos beati Cristophori martiris tui meritis \u8230 \'85\plain \f2\lang1033\fs22 ; >\plain \f2\i\lang1033\fs22 VII kalendas apriles natale sancti Livdgeri\plain \f2\lang1033\fs22 <. \plain \f2\i\lang1033\fs22 Deus qui beatum Liudgerum confessorem tuum\plain \f2\lang1033\fs22 \u8230 \'85\endash \u8230 \'85 \plain \f2\i\lang1033\fs22 praemia consequi mereamur\plain \f2\lang1033\fs22  CO Nr. 4237. \endash Lit.: Droegereit, Einheit, S. 130 mit Anm. 13.}

