\pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa195\itap0 \plain \f2\lang1033\fs22 218v\endash 224v {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f2\scaps\lang1033\fs22\chcbpat17 Exorcismi, benedictiones et orationes diversi}}\plain \f2\i\lang1033\fs24  (218v) >\plain \f2\i\lang1033\fs22 Exorcismus salis\plain \f2\lang1033\fs22 < Deshusses Nr. 1451; >\plain \f2\i\lang1033\fs22 Benedictio salis\plain \f2\lang1033\fs22 < Deshusses Nr. 1452; (219r) >\plain \f2\i\lang1033\fs22 Exorcismus aqvae\plain \f2\lang1033\fs22 < Deshusses Nr. 1453; >\plain \f2\i\lang1033\fs22 Benedictio aqvae\plain \f2\lang1033\fs22 < Nr. 1454; >\plain \f2\i\lang1033\fs22 Benedictio salis et aqvae pariter\plain \f2\lang1033\fs22 < Deshusses Nr. 1455; (219v) >\plain \f2\i\lang1033\fs22 Oratio in sacrario\plain \f2\lang1033\fs22 < Deshusses Nr. 1473; >\plain \f2\i\lang1033\fs22 Oratio in cymiteriis\plain \f2\lang1033\fs22 < Deshusses Nr. 1447; >\plain \f2\i\lang1033\fs22 Oratio in scriptorio\plain \f2\lang1033\fs22 < Deshusses Nr. 1478; (220r) >\plain \f2\i\lang1033\fs22 Oratio in dormitorio\plain \f2\lang1033\fs22 < Deshusses Nr. 1476; >\plain \f2\i\lang1033\fs22 Oratio in cellario\plain \f2\lang1033\fs22 < Deshusses Nr. 1477; >\plain \f2\i\lang1033\fs22 Oratio in coqvina\plain \f2\lang1033\fs22 < Deshusses Nr. 1484; >\plain \f2\i\lang1033\fs22 Oratio in refectorio\plain \f2\lang1033\fs22 < Deshusses Nr. 1475; >\plain \f2\i\lang1033\fs22 In domo infirmorum\plain \f2\lang1033\fs22 < Deshusses Nr. 1480; (220v) >\plain \f2\i\lang1033\fs22 Oratio pro introevntibus in basilicam\plain \f2\lang1033\fs22 < CO Nr. 6075; >\plain \f2\i\lang1033\fs22 Orationes post processionem in ecclesia dicende\plain \f2\lang1033\fs22 < CO Nr. 5777b; (221r) >\plain \f2\i\lang1033\fs22 Benedictio salis ad pecora tvtanda<\plain \f2\i\lang1033\fs24  \plain \f2\i\lang1033\fs22 Deus inuisibilis deus inaestimabilis qui per cuncta diffusus es\u8230 \'85\plain \f2\lang1033\fs22  \endash  Ed.: Brauner, S. 404; >\plain \f2\i\lang1033\fs22 Pro peste animalium<\plain \f2\i\lang1033\fs24  \plain \f2\i\lang1033\fs22 Domine deus omnipotens sanetur creatura animalium\u8230 \'85\plain \f2\lang1033\fs22  \endash  Ed.: Andrieu, Bd. 2, S. 122; \plain \f2\i\lang1033\fs22 >Benedictio aqvae contra nociva animalia<\plain \f2\i\lang1033\fs24  \plain \f2\i\lang1033\fs22 Benedic domine hanc creaturam aquae ut fugiant\plain \f2\lang1033\fs22 \u8230 \'85 \endash  Ed.: Jolly, S. 121; >\plain \f2\i\lang1033\fs22 Benedictio domus\plain \f2\lang1033\fs22 < CO Nr. 133; (221v) [Benedictiones diversae] Deshusses Nr. 1458, 1464, 4089, 4358; (222r) Deshusses Nr. 4326; \plain \f2\i\lang1033\fs22 Ascendat benedictio Dei patris et filii et spiritus sancti super hanc creaturam panis\u8230 \'85\plain \f2\lang1033\fs22 ; Deshusses Nr. 4354, 4352, 4340; (222v) \plain \f2\i\lang1033\fs22 Domine omnipotens Jhesu Christe qui ex quinque panibus et duobus piscibus quinque milia hominum satiasti\u8230 \'85\plain \f2\lang1033\fs22 ; Deshusses Nr. 1252, 4366; (223r) Deshusses Nr. 4238, 4329, 4342; \plain \f2\i\lang1033\fs22 Benedic domine creaturam hanc arborum quam tua\u8230 \'85\plain \f2\lang1033\fs22 ; (223v) \plain \f2\i\lang1033\fs22 Deus domine qui paruulis ad te uenientibus\u8230 \'85\plain \f2\lang1033\fs22 ; Deshusses Nr. 4182; Ps 86; Ps 19; \plain \f3\i\lang1024\fs22 Da quaesumus domine famulo tuo spiritum sapienti\u281 \'ea\u8230 \'85\plain \f2\lang1033\fs22  vgl. Deshusses Nr. 2442; \plain \f2\i\lang1033\fs22 Adiuro te N per patrem et filium et spiritum sanctum et diem tremendi\plain \f2\lang1033\fs22  \plain \f2\i\lang1033\fs22 indicii\plain \f2\lang1033\fs22 \u8230 \'85; (224r) Deshusses Nr. 4498f. (= Harle\u223 \'df, S. 79; H\u246 \'f6derath, S. 8); CO Nr. 3112; (224v) Deshusses Nr. 2791.}

