\pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa195\itap0 \plain \f2\lang1033\fs22 232v\endash 234v {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f2\scaps\lang1033\fs22\chcbpat17 Missae diversae cum lectionibus}}\plain \f2\i\lang1033\fs24  (232v) \plain \f2\i\lang1033\fs22 Prefatio\plain \f2\lang1033\fs22  CSEL 160C, Nr. 1145; [Natale sancti Michaelis archangeli]; (233r) \plain \f2\i\lang1033\fs22 De sancto [!] cruce\plain \f2\lang1033\fs22 ; (234r) \plain \f2\i\lang1033\fs22 Tractus\plain \f2\i\lang1033\fs24  \plain \f2\i\lang1033\fs22\cf1 Te decet laus, te decet ymnus \plain \f2\lang1033\fs22\cf1 AH Bd. 43, Nr. 2, siehe auch Ms. D 3, fol. 25v; (234v) \plain \f2\i\lang1033\fs22\cf1 Vigilia sancti Albani martyris \plain \f2\lang1033\fs22\cf1 CO Nr. 938; \plain \f2\i\lang1033\fs22\cf1 Natale sancti Albani martyris \plain \f2\lang1033\fs22\cf1 CO Nr. 4514. \plain \f2\lang1033\fs22 \endash 235r\endash v leer.}

