\pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa195\itap0 \plain \f2\lang1033\fs22 1r\endash 3v {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f2\scaps\lang1033\fs22\chcbpat17 Kalendarium}}\plain \f2\i\lang1033\fs24  N\plain \f2\lang1033\fs22  achtr\u228 \'e4glich vorgebunden, Anfang kaum lesbar, Erg\u228 \'e4nzungen aus der 2. H\u228 \'e4lfte des 10. Jh.s.; Lat\plain \f2\i\lang1033\fs24 , \plain \f2\lang1033\fs22 Jan.\endash Dez.\plain \f2\scaps\lang1033\fs22 , \plain \f2\lang1033\fs22 Tagesbuchstaben, Kalenden, Nonen, Iden, Dies Aegyptiaci, mit einigen nekrologischen Eintr\u228 \'e4gen; abweichend vom Proprium de sanctis der Handschrift; bemerkenswert: \plain \f2\i\lang1033\fs22 Translacio sancte Pinnose\plain \f2\lang1033\fs22  (28. Febr.), \plain \f2\i\lang1033\fs22 Liudgeri \plain \f2\lang1033\fs22 (26. M\u228 \'e4rz),\plain \f2\i\lang1033\fs22 Gersuit \plain \f2\lang1033\fs22 (30. M\u228 \'e4rz); Nennung seltener Hll. und seltener Festtage, auch abweichend von Ms. D 1 und D 2: z.B. \plain \f2\i\lang1033\fs22 Basiliani\plain \f2\lang1033\fs22  (11. Febr.); oftmals abweichende Festtermine: z.B. \plain \f2\i\lang1033\fs22 Sancti Policarpi\plain \f2\lang1033\fs22  (1. Febr.), \plain \f2\i\lang1033\fs22 Erenei\plain \f2\lang1033\fs22  (5. Mai). \endash  Ed.: Boewe-Koob, Antiphonar, S. 357\endash 367. \endash  Lit.: Harle\u223 \'df, S. 80; Zilliken, S. 36\endash 127; Ilgen, Beitr\u228 \'e4ge, S. 149\endash 152; Levison, S. 29, 51; Niemeyer, S. 72; Huth, S. 241f., Anm. 156.}

