\pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa195\itap0 \plain \f2\lang1033\fs22 164r\endash 169r {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f2\scaps\lang1033\fs22\chcbpat17 Exorcismi, benedictiones et orationes diversae}}\plain \f2\i\lang1033\fs24  \plain \f2\lang1033\fs22  (164r) [Benedictio minor salis et aque], \plain \f2\i\lang1033\fs22 Exorcizo: Incipiunt exorcismi et benedictiones te creatura salis\plain \f2\lang1033\fs22 \u8230 \'85; \plain \f3\i\lang1024\fs22 Alia oratio: Immensam clementiam tuam omnipotens \u281 \'eatern\u281 \'ea deus\u8230 \'85\plain \f2\lang1033\fs22 ; (164v) \plain \f3\i\lang1024\fs22 Benedictio aqu\u281 \'ea:\plain \f2\lang1033\fs22  \plain \f3\i\lang1024\fs22 Exorcizo te creatura aqu\u281 \'ea, in nomine Dei patris omnipotentis\plain \f2\lang1033\fs22 \u8230 \'85; \plain \f2\i\lang1033\fs22 Oratio: Deus qui ad salutem humani generis marina\plain \f2\lang1033\fs22 \u8230 \'85; (165r) \plain \f2\i\lang1033\fs22 Deus inuicte uirtutis auctor et inseperabilis \plain \f2\lang1033\fs22 [!]\plain \f2\i\lang1033\fs22 imperii rex.\plain \f2\lang1033\fs22  \endash  Ed.: Franz, Bd. 1, Nr. 1\endash 5, H\u252 \'fcrlimann Nr. 1\endash 6, Arx Nr. 1\endash 6; (165r) \plain \f3\i\lang1024\fs22 Post aspersionem: Praesta domine Ihesu Christe per hanc creatur\u281 \'ea tu\u281 \'ea aspersionem\plain \f2\lang1033\fs22 \u8230 \'85; \plain \f2\i\lang1033\fs22 Benedictio super nouam domum: Omnipotens sempiterne deus insere te officiis nostris\plain \f2\lang1033\fs22 \u8230 \'85; \plain \f2\i\lang1033\fs22 Item alia: Exaudi nos domine sancte pater omnipotens sempiterne deus et mittere digneris\plain \f2\i\lang1033\fs24  \endash  Ed.: H\u252 \'fcrlimann Nr. 78; (165v) \plain \f2\i\lang1033\fs22 Item alia: Te deum patrem omnipotentem exoramus pro hac domo\plain \f2\lang1033\fs22 \u8230 \'85; \plain \f2\i\lang1033\fs22 Benedictio noue nauis\plain \f2\lang1033\fs22  CO Nr. 4689; \plain \f2\i\lang1033\fs22 Benedictio noui putei uel \plain \f3\i\lang1024\fs22 fontis: Deprecamur domine clementiam pietatis tu\u281 \'ea\plain \f2\lang1033\fs22 \u8230 \'85; (166r) \plain \f2\i\lang1033\fs22 Benedictio super quam libet aquam \plain \f2\lang1033\fs22 \endash Ed.: Dumas Nr. 2858; \plain \f2\i\lang1033\fs22 Benedictio super nouos fructus.\plain \f2\lang1033\fs22  \endash  Ed.: Dumas Nr. 2832; \plain \f2\i\lang1033\fs22 Benedictio super noua poma: Deus qui arbor es poma tua uissione \plain \f2\lang1033\fs22 [!]\plain \f2\i\lang1033\fs22 et prouidentia\plain \f2\lang1033\fs22 \u8230 \'85; Nachtrag: \plain \f2\i\lang1033\fs22 Benedictio vitii: Domine sancte pater omnipotens eterne deus benedicere digneris hanc creaturam\plain \f2\lang1033\fs22 \u8230 \'85; (166v) \plain \f2\i\lang1033\fs22 Benedictio super fructus arborum: Benedic domine hanc creaturam arborum quam tua nobis larguas\plain \f2\lang1033\fs22 \u8230 \'85; \plain \f3\i\lang1024\fs22 Benedictio uu\u281 \'ea: Benedic domine et hos fructus nouos uu\u281 \'ea\u8230 \'85\plain \f2\lang1033\fs22 ;\plain \f2\i\lang1033\fs22 Benedictio panis.\plain \f2\lang1033\fs22  \endash  Ed.: Dumas Nr. 2841; \plain \f2\i\lang1033\fs22 Item alia: Benedicere digneris hunc panem\u8230 \'85\plain \f2\lang1033\fs22 ; (167r) \plain \f2\i\lang1033\fs22 Benedictio casei: Dignare pater omnipotens benedicere\plain \f2\i\lang1033\fs24  \endash Ed.: Franz, Bd. 1, S. 593; \plain \f2\i\lang1033\fs22 Benedictio carnis.\plain \f2\lang1033\fs22  \endash Ed.: Dumas Nr. 2021, Arx Nr. 210; \plain \f2\i\lang1033\fs22 Benedictio ensis primum accingendi. \plain \f2\lang1033\fs22 \endash  Ed.: Arx Nr. 397; (167v) \plain \f2\i\lang1033\fs22 Item alia:\plain \f2\lang1033\fs22  \plain \f2\i\lang1033\fs22 Benedic domini sancte pater per inuocationem sancti nominis tui\plain \f2\lang1033\fs22 \u8230 \'85; \plain \f2\i\lang1033\fs22 Benedictio super peregrinantes. \plain \f2\lang1033\fs22 \endash Ed.: Arx Nr. 386\endash 388; (168r\endash v) [Benedictio super capsellas et fustes et super homines]. \plain \f2\i\lang1033\fs22 Domine Ihesu Christe mundi conditor et redemptor\plain \f2\lang1033\fs22 \u8230 \'85 \endash  \plain \f2\i\lang1033\fs22 Commissio fustium et capsellarum: In nomine domini accipite has capsellas\plain \f2\lang1033\fs22 \u8230 \'85 \endash  \plain \f2\i\lang1033\fs22 Omnipotens sempiterne deus humani generis auctor et reformator\plain \f2\lang1033\fs22 \u8230 \'85\endash \u8230 \'85 \plain \f2\i\lang1033\fs22 Saluos fac seruos\plain \f2\i\lang1033\fs24  \endash Ed.: Franz, Bd. 2, S. 275ff., Nr. I, 1\endash 3; \plain \f3\i\lang1024\fs22 Omnipotens sempiterne deus nostrorum temporum uit\u281 \'eaque dispositor. \plain \f2\lang1033\fs22 \endash Ed.: Dumas Nr. 1821, \plain \f2\i\lang1033\fs22 H\u252 \'fcrlimann\plain \f2\lang1033\fs22 , Nr. 108\endash 110 (mit k\u252 \'fcrzerer Oratio); (169r) [A]\plain \f2\i\lang1033\fs22 eterne deus mundi conditor omniumque creaturarum mirabilis dispositor\plain \f2\lang1033\fs22 \u8230 \'85, Gebet zur Palmweihe, sp\u228 \'e4terer Nachtrag.}

