\pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa195\itap0 \plain \f2\lang1033\fs22 258va\endash 264v {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f2\scaps\lang1033\fs22\chcbpat17 Hymnarium, Hymni de sanctis et de commune sanctorum}}\plain \f2\i\lang1033\fs24  (258va) >\plain \f2\i\lang1033\fs22 Sanctorum innocentum ad matutinam<. Qve vox que poterit \plain \f2\lang1033\fs22 AH Bd. 50, Nr. 153, Str. 5\endash 6 von \u8218 \'82Sanctorum meritis inclita gaudia\lquote ;(258vb) \plain \f2\i\lang1033\fs22 >In laudibus<\plain \f2\i\lang1033\fs24  \plain \f2\i\lang1033\fs22 Katerva matrum personat\plain \f2\lang1033\fs22  AH Bd. 50, Nr. 53, Str. 10 von \u8218 \'82A solis ortus cardine\lquote ; >\plain \f2\i\lang1033\fs22 In conuersione sancti Pauli ad ueperas et ad matutinam\plain \f2\lang1033\fs22 <. \plain \f2\i\lang1033\fs22 Doctor egregie \plain \f2\lang1033\fs22 AH Bd. 23, Nr. 450, Str. 1, 5; (259ra) >\plain \f2\i\lang1033\fs22 In laudibus in festo purificationes ad vesperas\plain \f2\lang1033\fs22 <. \plain \f2\i\lang1033\fs22 Ave maris stella \plain \f2\lang1033\fs22 AH Bd. 51, Nr. 123; (259rb) >\plain \f2\i\lang1033\fs22 Ad matutinam\plain \f2\lang1033\fs22 <. \plain \f2\i\lang1033\fs22 Quem terra pontus\plain \f2\lang1033\fs22  AH Bd. 2, Nr. 27, Str. 1\endash 2, 4; (259va) >\plain \f2\i\lang1033\fs22 De beata uirgine in laudibus\plain \f2\lang1033\fs22 <. \plain \f2\i\lang1033\fs22 O gloriosa domina\plain \f2\lang1033\fs22  AH Bd. 50, Nr. 72, Str. 6\endash 8 von \u8218 \'82Quem terra pontus aethera\lquote \plain \f2\i\lang1033\fs24  \endash Lit.: St\u228 \'e4blein, Hymnen (I), S. XVI; (259vb) >\plain \f2\i\lang1033\fs22 In cathedra sancti Petri ad vesperam et ad matutinam\plain \f2\lang1033\fs22 <. \plain \f2\i\lang1033\fs22 Iam bone pastor\plain \f2\lang1033\fs22  AH Bd. 51, Nr. 188, Str. 3, 6 von \u8218 \'82Aurea luce et decore roseo\lquote ; >\plain \f2\i\lang1033\fs22 In laudibus\plain \f2\lang1033\fs22 <. \plain \f2\i\lang1033\fs22 Ihesu redemptor\plain \f2\lang1033\fs22 ; >\plain \f2\i\lang1033\fs22 In annunciatione ad uesperas\plain \f2\lang1033\fs22 <. [A]\plain \f2\i\lang1033\fs22 ue maris stella\plain \f2\lang1033\fs22 ; (260ra) >\plain \f2\i\lang1033\fs22 Ad matutinam\plain \f2\lang1033\fs22 <. \plain \f2\i\lang1033\fs22 Quem terra\plain \f2\lang1033\fs22 ; >\plain \f2\i\lang1033\fs22 In laudibus\plain \f2\lang1033\fs22 <. \plain \f2\i\lang1033\fs22 O gloriosa domina\plain \f2\lang1033\fs22 ; >\plain \f2\i\lang1033\fs22 In festis apostolorum et ewangeliorum ad vesperam et ad matutinam ymnus\plain \f2\lang1033\fs22 <. \plain \f2\i\lang1033\fs22 Exultet celum laudibus \plain \f2\lang1033\fs22 AH Bd. 51, Nr. 108; >\plain \f2\i\lang1033\fs22 In laudibus\plain \f2\lang1033\fs22 <. \plain \f2\i\lang1033\fs22 Eterna Christi munera apostolorum\plain \f2\lang1033\fs22  AH Bd. 50, Nr. 17, Str. 1\endash 2, 6\endash 8; (260rb) >\plain \f2\i\lang1033\fs22 In festo vnius martiris ad vesperam et ad matutinam\plain \f2\lang1033\fs22 <. \plain \f2\i\lang1033\fs22 Deus tuorum militum fors\plain \f2\lang1033\fs22  AH Bd. 51, Nr. 114a; >\plain \f2\i\lang1033\fs22 In laudibus\plain \f2\lang1033\fs22 <. \plain \f2\i\lang1033\fs22 Martir Dei qui unicum patris\plain \f2\lang1033\fs22  AH Bd. 51, Nr. 113; (260va) >\plain \f2\i\lang1033\fs22 In festo simplici plurimorum martyrum ad uesperam et ad matutinam\plain \f2\lang1033\fs22 <. \plain \f2\i\lang1033\fs22 Sanctorum meritis inclita gaudia \plain \f2\lang1033\fs22 AH Bd. 50, Nr. 153; (260vb) >\plain \f2\i\lang1033\fs22 In festo trium lectionum\plain \f2\lang1033\fs22 <. \plain \f2\i\lang1033\fs22 Sanctorum meritis inclita gaudia\plain \f2\lang1033\fs22 , Text wie oben, weitere Melodie; (261ra) >\plain \f2\i\lang1033\fs22 In laudibus\plain \f2\lang1033\fs22 <. \plain \f2\i\lang1033\fs22 Eterna Christi munera et martirum\plain \f2\lang1033\fs22  AH Bd. 50, Nr. 17, Str. 1, 3\endash 5, 8; (261rb) >\plain \f2\i\lang1033\fs22 In festo semiduplici unius confessoris ad uesperas et ad matutinas\plain \f2\lang1033\fs22 <. \plain \f2\i\lang1033\fs22 Iste confessor domini sacratus \plain \f2\lang1033\fs22 AH Bd. 51, Nr. 118; >\plain \f2\i\lang1033\fs22 In festo simplici\plain \f2\lang1033\fs22 <. \plain \f2\i\lang1033\fs22 Iste confessor domini sacratus\plain \f2\lang1033\fs22  AH Bd. 51, Nr. 118, Str. 1; (261va) >\plain \f2\i\lang1033\fs22 In festo trium lectionum\plain \f2\lang1033\fs22 <. \plain \f2\i\lang1033\fs22 Iste confessor domini sacratus\plain \f2\lang1033\fs22 , Text wie oben, weitere Melodie; >\plain \f2\i\lang1033\fs22 In laudibus<. Ihesu redemptor omnium corona\plain \f2\lang1033\fs22  AH Bd. 51, Nr. 117; (261vb) >\plain \f2\i\lang1033\fs22 In festo simplici unius virginis ad vesperam et ad matutinam ymnus\plain \f2\lang1033\fs22 <. \plain \f2\i\lang1033\fs22 Virginis proles opifexque matris\plain \f2\lang1033\fs22  AH Bd. 51, Nr. 121; (262ra) >\plain \f2\i\lang1033\fs22 In festo trium lectionum\plain \f2\lang1033\fs22 <. \plain \f2\i\lang1033\fs22 Virginis proles opifexque matris\plain \f2\lang1033\fs22 , Text wie oben, weitere Melodie; >\plain \f2\i\lang1033\fs22 In laudibus\plain \f2\lang1033\fs22 <. \plain \f2\i\lang1033\fs22 Ihesu corona uirginum\plain \f2\lang1033\fs22  AH Bd. 50, Nr. 21; (262rb) >\plain \f2\i\lang1033\fs22 In festis totis duplicibus et duplicibus\plain \f2\lang1033\fs22 <.\plain \f2\i\lang1033\fs22 Iam lucis orto sydere\plain \f2\lang1033\fs22 , Text wie oben, weitere Melodie; >\plain \f2\i\lang1033\fs22 In festis semiduplicibus\plain \f2\lang1033\fs22 <. \plain \f2\i\lang1033\fs22 Iam lucis orto sydere\plain \f2\lang1033\fs22 , Text wie oben, weitere Melodie; (262va) >\plain \f2\i\lang1033\fs22 In festo simplici\plain \f2\lang1033\fs22 <. \plain \f2\i\lang1033\fs22 Iam lucis orto sydere\plain \f2\lang1033\fs22 , Text wie oben, weitere Melodie; >\plain \f2\i\lang1033\fs22 In festo trium lectionum\plain \f2\lang1033\fs22 <. \plain \f2\i\lang1033\fs22 Iam lucis orto sydere\plain \f2\lang1033\fs22 , Text wie oben, weitere Melodie; >\plain \f2\i\lang1033\fs22 Infra octavas\plain \f2\lang1033\fs22 <.\plain \f2\i\lang1033\fs22 Iam lucis orto sydere\plain \f2\lang1033\fs22 , Text wie oben, weitere Melodie; (262vb) >\plain \f2\i\lang1033\fs22 In sabbatis de beata uirgine\plain \f2\lang1033\fs22 <. \plain \f2\i\lang1033\fs22 Aue maris stella\plain \f2\lang1033\fs22 , Text wie oben, weitere Melodie; >\plain \f2\i\lang1033\fs22 Ad matutinam\plain \f2\lang1033\fs22 <. \plain \f2\i\lang1033\fs22 Quem terra pontus\plain \f2\lang1033\fs22 , Text wie oben, weitere Melodie; im Folgenden sind die Anf\u228 \'e4nge der schon zuvor angef\u252 \'fchrten Hymnen angegeben mit dem Hinweis, wann sie noch zu singen sind.}

