\pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa195\itap0 \plain \f2\lang1033\fs22 4r\endash 89r {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f2\scaps\lang1033\fs22\chcbpat17 Antiphonale officii, Proprium de tempore}}\plain \f2\i\lang1033\fs24  Sommerteil, Beginn mit den Antiphonen und dem Responsorium zur ersten Vesper von Ostern (Karsamstag) bis \plain \f2\i\lang1033\fs22 Dominica XXV\plain \f2\lang1033\fs22  und zum Kirchweihfest. Der Inhalt entspricht dem Ordinarium des dominikanischen Prototyps, Guerrini Nr. 158\endash 249. (4r) >\plain \f2\i\lang1033\fs22 Sabbato sancto ad vesperas\plain \f2\lang1033\fs22 <; [In die paschae], mit Sequenz \plain \f2\i\lang1033\fs22 Victime paschali laudes\plain \f2\lang1033\fs22  AH Bd. 54, Nr. 7; (16r) >\plain \f2\i\lang1033\fs22 Dominica in octava pasche\plain \f2\lang1033\fs22 <; (21v) >\plain \f2\i\lang1033\fs22 Dominica Ia post octavam pasche\plain \f2\lang1033\fs22 <; (22r) >\plain \f2\i\lang1033\fs22 Dominica IIa post octavam pasche\plain \f2\lang1033\fs22 <; (23r) >\plain \f2\i\lang1033\fs22 Dominica IIIa post octavam pasche\plain \f2\lang1033\fs22 <; (26r) >\plain \f2\i\lang1033\fs22 Dominica IIIIa\plain \f2\lang1033\fs22 <; >\plain \f2\i\lang1033\fs22 Feria IIa et IIIa in rogationibus\plain \f2\lang1033\fs22 <; (26v) >\plain \f2\i\lang1033\fs22 In vigilia ascensionis\plain \f2\lang1033\fs22 <; (27r) [In die]; (32r) >\plain \f2\i\lang1033\fs22 Dominica infra octavam ascensionis\plain \f2\lang1033\fs22 <; (33r) >\plain \f2\i\lang1033\fs22 In vigilia pentecostes\plain \f2\lang1033\fs22 <; (33v) [In die]; (42r) >\plain \f2\i\lang1033\fs22 In festo sancte trinitatis\plain \f2\lang1033\fs22 <; (48v) >\plain \f2\i\lang1033\fs22 Dominica prima post festum trinitatis\plain \f2\lang1033\fs22 <; (54v) >\plain \f2\i\lang1033\fs22 Dominica prima augusti\plain \f2\lang1033\fs22 <; (58v) >\plain \f2\i\lang1033\fs22 Dominica prima septembris\plain \f2\lang1033\fs22 <; (62r) >\plain \f2\i\lang1033\fs22 Dominica IIIa septembris\plain \f2\lang1033\fs22 <; (66v) >\plain \f2\i\lang1033\fs22 Dominica Ia octobris\plain \f2\lang1033\fs22 <; (69r) >\plain \f2\i\lang1033\fs22 Dominica Ia nouembris\plain \f2\lang1033\fs22 <; (73r) >\plain \f2\i\lang1033\fs22 Dominica prima post festum trinitatis\plain \f2\lang1033\fs22 <; (73v) >\plain \f2\i\lang1033\fs22 Dominica secunda\plain \f2\lang1033\fs22 <; (74r) >\plain \f2\i\lang1033\fs22 Dominica tertia\plain \f2\lang1033\fs22 <; >\plain \f2\i\lang1033\fs22 Dominica quarta\plain \f2\lang1033\fs22 <; (74v) >\plain \f2\i\lang1033\fs22 Dominica quinta\plain \f2\lang1033\fs22 <; >\plain \f2\i\lang1033\fs22 Dominica VIa\plain \f2\lang1033\fs22 <; im Folgenden fehlen die Rubriken f\u252 \'fcr die Sonntage, am Rand ist eine Sonntagsz\u228 \'e4hlung in schwarzer Tinte nachgetragen, teilweise in den Zahlen differierend, stark beschnitten: (75r) [Dominica septima]; (75v) [Dominica octava]; (76r) [Dominica nona]; (76v) [Dominica decima]; (77r) [Dominica undecima]; (77v) [Dominica duodecima]; [Dominica tertia decima]; (78r) [Dominica quarta decima]; (78v) [Dominica quinta decima]; [Dominica sexta decima]; (79r) [Dominica decima septima]; (79v) [Dominica decima octava]; (80r) [Dominica decima nona]; [Dominica vigesima]; (80v) >\plain \f2\i\lang1033\fs22 Dominica XXIa\plain \f2\lang1033\fs22 <; >\plain \f2\i\lang1033\fs22 Dominica XXIIa\plain \f2\lang1033\fs22 <; (81r) >\plain \f2\i\lang1033\fs22 Dominica XXIIIa\plain \f2\lang1033\fs22 <; (81v) >\plain \f2\i\lang1033\fs22 Dominica XXIIIIa\plain \f2\lang1033\fs22 <; >\plain \f2\i\lang1033\fs22 Dominica XXVa\plain \f2\lang1033\fs22 <; (82r) >\plain \f2\i\lang1033\fs22 In dedicatione templi\plain \f2\lang1033\fs22 <.}

