\pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa195\itap0 \plain \f2\lang1033\fs22 300rb\endash 300vb >\plain \f2\i\lang1033\fs22 In festo sancti Iohannis apostoli et ewangeliste ymnus ad vesperas\plain \f2\lang1033\fs22 <. \plain \f2\i\lang1033\fs22 A patre uerbum\plain \f2\lang1033\fs22  AH Bd. 51, Bd. 161, Str.1\endash 3,\plain \f2\i\lang1033\fs22 Uiuens adhuc corpore\plain \f2\lang1033\fs22  AH Bd. 16, Nr. 278, Str. 3, \plain \f2\i\lang1033\fs22 Cuius prece assidua\plain \f2\lang1033\fs22  AH Bd. 51, Nr. 160, Str. 6; (300va) >\plain \f2\i\lang1033\fs22 Ad matutinas\plain \f2\lang1033\fs22 <. \plain \f2\i\lang1033\fs22 Ascendens crucis arborem\plain \f2\lang1033\fs22  Divisio des vorigen Hymnus, Str. 4\endash 7; (300vb) >\plain \f2\i\lang1033\fs22 In laudibus\plain \f2\lang1033\fs22 <. \plain \f2\i\lang1033\fs22 Gaudete cum leticia\plain \f2\lang1033\fs22 , bricht ab. \endash  301r\endash v leer.}

