\pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs22 42r\endash 43r {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs22\chcbpat17 Orationes}}\plain \f1\lang1033\fs22  , sonst Bestandteil des Totenoffiziums und der Allerheiligenliturgie. \plain \f1\i\lang1033\fs22 Anime omnium fidelium defunctorum\plain \f1\lang1033\fs22  \plain \f1\i\lang1033\fs22 per\plain \f1\lang1033\fs22  \plain \f1\i\lang1033\fs22 misericordiam dei requiescant\plain \f1\lang1033\fs22 , vgl. Burnet Psalter, Aberdeen, Marischal College, fol. 321r; Rostock, UB, Ms. theol. 27a, fol. 219rb; >\plain \f1\i\lang1033\fs22 Ps\plain \f1\i\lang1033\fs24 <. \plain \f1\i\lang1033\fs22 Deus misereatur nostri et benedicat nobis\plain \f1\lang1033\fs22  (Ps 66); \plain \f1\i\lang1033\fs22 Gloria\plain \f1\lang1033\fs22 ; >\plain \f1\i\lang1033\fs22 Versus\plain \f1\lang1033\fs22 <. \plain \f1\i\lang1033\fs22 Domine deus virtutum converte nos\plain \f1\i\lang1033\fs24  >\plain \f1\i\lang1033\fs22 Versus\plain \f1\lang1033\fs22 <. \plain \f1\i\lang1033\fs22 Exurge\plain \f1\lang1033\fs22  \plain \f1\i\lang1033\fs22 domine adiuva nos\plain \f1\lang1033\fs22 ; \plain \f1\i\lang1033\fs22 Deus qui illuminas noctem\plain \f1\lang1033\fs22 ; \plain \f1\i\lang1033\fs22 Protector in te sperantium deus;\plain \f1\lang1033\fs22  >\plain \f1\i\lang1033\fs22 Pro fidelibus defunctis. Ps\plain \f1\i\lang1033\fs24 <. \plain \f1\i\lang1033\fs22 De profundis clamavi\plain \f1\lang1033\fs22  ; (Ps 129); >\plain \f1\i\lang1033\fs22 Versus\plain \f1\lang1033\fs22 <. \plain \f1\i\lang1033\fs22 Requiem eternam dona eis domine\plain \f1\lang1033\fs22 ; >\plain \f1\i\lang1033\fs22 Oratio\plain \f1\lang1033\fs22 <. \plain \f1\i\lang1033\fs22 Deus qui inter apostolicos sacerdotes\plain \f1\lang1033\fs22  Bruylants, Oraisons, Bd. 2, Nr. 375; \plain \f1\i\lang1033\fs22 Deus venie largitor\plain \f1\lang1033\fs22  Bruylants, Oraisons, Bd. 2, Nr. 465; \plain \f1\i\lang1033\fs22 Fidelium deus omnium conditor\plain \f1\lang1033\fs22  Bruylants, Oraisons, Bd. 2, Nr. 567.}

