\pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs22 44v\endash 45r{\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs22\chcbpat17 Orationes ad sanctam trinitatem}}\plain \f1\i\lang1033\fs24  >\plain \f1\i\lang1033\fs22 De sancta trinitate\plain \f1\lang1033\fs22 <. \plain \f1\i\lang1033\fs22 Libera nos, salva nos\plain \f1\lang1033\fs22  CAO 3619; \plain \f1\i\lang1033\fs22 Benedicat me semper imperialis maiestas\plain \f1\lang1033\fs22  Leroquais, Bd. 2, S. 68; >\plain \f1\i\lang1033\fs22 Oratio devota ad sanctam trinitatem\plain \f1\lang1033\fs22 <. \plain \f1\i\lang1033\fs22 Domine deus omnipotens pater et filius et spiritus sanctus. Da michi famulo tuo\plain \f1\lang1033\fs22  \plain \f1\i\lang1033\fs22 victoriam contra omnes inimicos meos \plain \f1\lang1033\fs22 Leroquais, Bd. 1, S. 323; >\plain \f1\i\lang1033\fs22 De mane quando quis surgit. Oratio bona\plain \f1\lang1033\fs22 <. \plain \f1\i\lang1033\fs22 Gracias tibi ago domine sancte pater omnipotens eterne deus qui me dignatus es in hac nocte\plain \f1\lang1033\fs22 , vgl. Leroquais, Bd. 1, S. 234.}

