\pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs22 46v\endash 48v {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs22\chcbpat17 Orationes devotae}}\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs22  >\plain \f1\i\lang1033\fs22 Ad sanctissimum sacramentum. Oratio\plain \f1\lang1033\fs22 <. \plain \f1\i\lang1033\fs22 Anima Christi sanctifica me corpus Christi salva me\plain \f1\lang1033\fs22  RH 1090; (47r) >\plain \f1\i\lang1033\fs22 Alia devota oratio\plain \f1\lang1033\fs22 <. \plain \f1\i\lang1033\fs22 Misericordissime piissime et benignissime domine Jhesu Christe precor te per infinitam misericordiam\plain \f1\lang1033\fs22 ; \plain \f1\i\lang1033\fs22 Ave domine Jhesu Christe verbum patris, filius virginis agnus dei salus mundi\plain \f1\lang1033\fs22  , vgl. Hore ad usum Sarum 1506: Kopenhagen, Kongelige Bibliotek, CMB, Pergament 19 4\u176 \'b0, fol. 86r; (47v) \plain \f1\i\lang1033\fs22 Ave caro Christi cara immolata crucis ara\plain \f1\lang1033\fs22  RH 1710; (48r) \plain \f1\i\lang1033\fs22 Deus qui voluisti pro salute et redemptione mundi nasci \plain \f1\lang1033\fs22 Leroquais, Bd. 1, S. 183, 233.}

