\pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs22 59r\endash 60r {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs22\chcbpat17 Orationes de quinque doloribus Mariae}}\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs22  >\plain \f1\i\lang1033\fs22 Oratio prima\plain \f1\lang1033\fs22 <. \plain \f1\i\lang1033\fs22 Mediatrix dei et hominum\plain \f1\lang1033\fs22  \plain \f1\i\lang1033\fs22 fons misericordie\plain \f1\lang1033\fs22 , vgl. Haimerl, Gebetbuchliteratur, S. 92, Anm. 549; >\plain \f1\i\lang1033\fs22 Oratio secunda\plain \f1\lang1033\fs22 <. \plain \f1\i\lang1033\fs22 Auxiliatrix omnium hominum et pacis eterne\plain \f1\lang1033\fs22 , vgl. Paris, BN, Ms. lat. 10734, fol. 144v; (59v) >\plain \f1\i\lang1033\fs22 Oratio tertia\plain \f1\lang1033\fs22 <. \plain \f1\i\lang1033\fs22 Reparatrix debilium et vulnerate anime\plain \f1\lang1033\fs22  Leroquais, Bd. 2, S. 26, 61; >\plain \f1\i\lang1033\fs22 Quarta oratio\plain \f1\lang1033\fs22 <. \plain \f1\i\lang1033\fs22 Illuminatrix cecorum et lucerna salutifere gratie Maria\plain \f1\lang1033\fs22 , vgl. Paris, BN, Ms. lat. 10734, fol. 145r; (60r) >\plain \f1\i\lang1033\fs22 Quinta oratio\plain \f1\lang1033\fs22 <. \plain \f1\i\lang1033\fs22 Advocatrix omnium peccatorum\plain \f1\lang1033\fs22  \endash  vgl. Druck: Michael M\u252 \'fcller, Exercitatio theologica inauguralis, De sanctorum invocatione, T\u252 \'fcbingen 1682, S. 30.}

