\par \pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa195\itap0 Nachtr\u228 \'e4ge an den Seitenr\u228 \'e4ndern, 16.\endash 18. Jh.: insgesamt 69 Festtagsdaten und einige Tractus als Erg\u228 \'e4nzungen von verschiedenen neuzeitlichen H\u228 \'e4nden: (371) \plain \f2\i\lang1033\fs22 Sanctae Martinae virginis et martyris\plain \f2\lang1033\fs22 ; \plain \f2\i\lang1033\fs22 In festo sanctae Bibianae virginis et martyris\plain \f2\lang1033\fs22 ; \plain \f2\i\lang1033\fs22 Sanctae Barbarae\plain \f2\lang1033\fs22 ; \plain \f2\i\lang1033\fs22 In festo conceptione beate virginis\plain \f2\lang1033\fs22 ; \plain \f2\i\lang1033\fs22 Sancti Damasi\plain \f2\lang1033\fs22 ; (378) \plain \f2\i\lang1033\fs22 Sancti Hilarii confessoris\plain \f2\lang1033\fs22 , \plain \f2\i\lang1033\fs22 Sancti Raymundi confessoris\plain \f2\lang1033\fs22  , \plain \f2\i\lang1033\fs22 Cathedra sancti Romanae Petri\plain \f2\lang1033\fs22 ; (382) \plain \f2\i\lang1033\fs22 Sanctae Emerentianae virginis\plain \f2\lang1033\fs22 ; \plain \f2\i\lang1033\fs22 Sancti Timothei martyris\plain \f2\lang1033\fs22 ; (385) \plain \f2\i\lang1033\fs22 Sancti Pauli Eremitae\plain \f2\lang1033\fs22 ; \plain \f2\i\lang1033\fs22 Sancti Polycarpi martyris\plain \f2\lang1033\fs22 ; \plain \f2\i\lang1033\fs22 Sancti Joannis Chrysostomi\plain \f2\lang1033\fs22 ; \plain \f2\i\lang1033\fs22 Sancti Juliani confessoris\plain \f2\lang1033\fs22 ; \plain \f2\i\lang1033\fs22 Sanctae Martinae\plain \f2\lang1033\fs22  \plain \f2\i\lang1033\fs22 virginis et martyris\plain \f2\lang1033\fs22 ; \plain \f2\i\lang1033\fs22 Sancti Ignatis martyris\plain \f2\lang1033\fs22 ; (388) \plain \f2\i\lang1033\fs22 Sanctae Dorotheae virginis\plain \f2\lang1033\fs22 ; \plain \f2\i\lang1033\fs22 Sancti Romualdi confessoris\plain \f2\lang1033\fs22 ; \plain \f2\i\lang1033\fs22 Sancti Apolloniae virginis\plain \f2\lang1033\fs22 ; \plain \f2\i\lang1033\fs22 Sanctae Scholasticae virginis\plain \f2\lang1033\fs22 ; (391) Hinweis auf Tr.: \plain \f2\i\lang103