\pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa195\itap0 \plain \f2\lang1033\fs22 74r\endash 93r {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f2\scaps\lang1033\fs22\chcbpat17 Proprium de sanctis}}\plain \f2\i\lang1033\fs24  \plain \f2\lang1033\fs22 Antiphonen zu den kleinen Horen. Vom Fest des hl. Stephanus (26. Dez.) bis zum Fest der Empf\u228 \'e4ngnis Mariens (8. Dez.). (74r) >\plain \f2\i\lang1033\fs22 In natali sancti Stephani prothomartiris\plain \f2\lang1033\fs22 <; (74v) >\plain \f2\i\lang1033\fs22 In natali sancti Iohannis euangeliste\plain \f2\lang1033\fs22 <; (75v) >\plain \f2\i\lang1033\fs22 Sanctorum innocentum martyrum\plain \f2\lang1033\fs22 <; (76r) >\plain \f2\i\lang1033\fs22 Agnetis virginis et martyris\plain \f2\lang1033\fs22 <; (76v) >\plain \f2\i\lang1033\fs22 In conuersione sancti Pauli apostoli\plain \f2\lang1033\fs22 <; (77v) >\plain \f2\i\lang1033\fs22 Purificationis beate Marie virginis<\plain \f2\lang1033\fs22 ; (78v) >\plain \f2\i\lang1033\fs22 Agathe virginis et martyris\plain \f2\lang1033\fs22 <; (79v) >\plain \f2\i\lang1033\fs22 In cathedra sancti Petri apostoli\plain \f2\lang1033\fs22 <; (80r) >\plain \f2\i\lang1033\fs22 Benedicti abbatis\plain \f2\lang1033\fs22 <; (81r) >\plain \f2\i\lang1033\fs22 In festo annunciationis dominice\plain \f2\lang1033\fs22 <; (82v) >\plain \f2\i\lang1033\fs22 In natiuitate sancti Iohannis baptiste\plain \f2\lang1033\fs22 <; (83r) >\plain \f2\i\lang1033\fs22 In natali sanctorum Petri et Pauli apostolorum\plain \f2\lang1033\fs22 <; >\plain \f2\i\lang1033\fs22 In commemoratione sancti Pauli apostoli\plain \f2\lang1033\fs22 <; (83v) >\plain \f2\i\lang1033\fs22 In octava sancti Iohannis baptiste\plain \f2\lang1033\fs22 <; >\plain \f2\i\lang1033\fs22 Visitationis beate Marie virginis\plain \f2\lang1033\fs22 <; (84r) >\plain \f2\i\lang1033\fs22 In commemoracione sancti Benedicti abbatis\plain \f2\lang1033\fs22 <; >\plain \f2\i\lang1033\fs22 Marie Magdalene\plain \f2\lang1033\fs22 <; (85r