\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f2\lang1033\fs22 390r\endash 404v {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f2\scaps\lang1033\fs22\chcbpat17 Hymnar}}\plain \f2\i\lang1033\fs24  Hymni de sanctis. (390r) >\plain \f2\i\lang1033\fs22 De sancto Andrea apostolo\plain \f2\lang1033\fs22 <. \plain \f2\i\lang1033\fs22 Post Petrum primum principem\plain \f2\lang1033\fs22  AH Bd. 51, Nr. 139; (391r) >\plain \f2\i\lang1033\fs22 Divisio\plain \f2\lang1033\fs22 <. \plain \f2\i\lang1033\fs22 Fallax ad patibulum\plain \f2\lang1033\fs22  RH 5951; (391v) >\plain \f2\i\lang1033\fs22 In omnibus sollemnitatibus dive virginis et martiris Marie\plain \f2\lang1033\fs22 <; \plain \f2\i\lang1033\fs22 Misterium ecclesie hymnum \plain \f2\lang1033\fs22 AH Bd. 51, Nr. 121; (392r) >\plain \f2\i\lang1033\fs22 Divisio\plain \f2\lang1033\fs22 <. \plain \f2\i\lang1033\fs22 Vere gracia plena \plain \f2\lang1033\fs22 RH 21408; (392v) >\plain \f2\i\lang1033\fs22 Ad completorium eiusdem gloriose virginis\plain \f2\lang1033\fs22 <. \plain \f2\i\lang1033\fs22 Ave maris stella\plain \f2\lang1033\fs22  AH Bd. 51, Nr. 123; Bd. 2, Nr. 29; (393v) >\plain \f2\i\lang1033\fs22 Beatissime dei genitricis semperque virginis Marie ad tertiam\plain \f2\lang1033\fs22 <. \plain \f2\i\lang1033\fs22 O quam glorifica luce coruscas \plain \f2\lang1033\fs22 AH Bd. 2, Nr. 30; (394r) >\plain \f2\i\lang1033\fs22 Stephani prothomartiris\plain \f2\lang1033\fs22 <. \plain \f2\i\lang1033\fs22 Stephani primi martyris\plain \f2\lang1033\fs22  RH 19483, vgl. AH Bd. 14a, Nr. 13, mit Abweichungen; (394v) >\plain \f2\i\lang1033\fs22 Divisio\plain \f2\lang1033\fs22 <. \plain \f2\i\lang1033\fs22 O preferenda gloria\plain \f2\lang1033\fs22  RH 13430; (395v) >\plain \f2\i\lang1033\fs22 Johannis apostoli et evangeliste\plain \f2\lang1033\fs22 <. \plain \f2\i\lang1033\fs22 Amore Christi nobilis\plain \f2\lang1033\fs22  AH Bd. 50, Nr. 9; (396r) >\plain \f2\i\lang1033\fs22 Divisio\plain \f2\lang1033\fs22