\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f2\lang1033\fs22 595\endash 644 {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f2\scaps\lang1033\fs22\chcbpat17 Hymnar}}\plain \f2\scaps\lang1033\fs22 , \plain \f2\lang1033\fs22 Hymni de tempore et de sanctis. (595) >\plain \f2\i\lang1033\fs22 Per adventum ad completorium exceptis festis sanctorum\plain \f2\lang1033\fs22 <. \plain \f2\i\lang1033\fs22 Quem terra pontus\plain \f2\lang1033\fs22  AH Bd. 50, Nr. 72; (596) >\plain \f2\i\lang1033\fs22 Ad tertiam eisdem diebus preter festa sanctorum\plain \f2\lang1033\fs22 <. \plain \f2\i\lang1033\fs22 Conditor alme siderum\plain \f2\lang1033\fs22  AH Bd. 51, Nr. 47; (597) >\plain \f2\i\lang1033\fs22 In nativitate domini\plain \f2\lang1033\fs22 <. \plain \f2\i\lang1033\fs22 Intende qui regis Israel\plain \f2\lang1033\fs22  AH Bd. 50, Nr. 8; (598) >\plain \f2\i\lang1033\fs22 Divisio\plain \f2\lang1033\fs22 <. \plain \f2\i\lang1033\fs22 Procedit de thalamo suo pudoris\plain \f2\lang1033\fs22 , vgl. James Mearns: Early Latin Hymnaries. An Index of Hymns in Hymnaries before 1100, Cambridge 1913, S. 69; (599) >\plain \f2\i\lang1033\fs22 Ad completorium usque ad octavas epiphanie\plain \f2\lang1033\fs22 <.\plain \f2\i\lang1033\fs22 Enixa est puerpera\plain \f2\lang1033\fs22 , vgl. AH Bd. 50, Nr. 53, Str. 5\endash 7; (601) >\plain \f2\i\lang1033\fs22 Ad tertiam eodem tempore sine intermissione\plain \f2\lang1033\fs22 <. \plain \f2\i\lang1033\fs22 A solis ortus cardine\plain \f2\lang1033\fs22 , vgl. AH Bd. 50, Nr. 53; (602) >\plain \f2\i\lang1033\fs22 In epiphania domini\plain \f2\lang1033\fs22 <. \plain \f2\i\lang1033\fs22 Illuminans altissimus micantium\plain \f2\lang1033\fs22  AH Bd. 50, Nr. 10; (604) >\plain \f2\i\lang1033\fs22 Ad nocturnos\plain \f2\lang1033\fs22 <. \plain \f2\i\lang1033\fs22 Intende qui regis Israel\plain \f2\lang1033\fs22  AH Bd. 50, Nr. 8; (605) >\plain \f2\i\lang1033\fs22 In natali prothomartyris Stephani\plain \f2\lang1033\fs22 <. \plain \f2\i\lang1033\fs22 Stephani primi martyris \plain \f2\lang1033\fs22 RH 19483; vgl. AH Bd. 14a, Nr. 13, mit Abweichungen; (606) >\plain \f2\i\lang1033\fs22 Divisio\plain \f2\lang1033\fs22 <. \plain \f2\i\lang1033\fs22 O preferenda gloria\plain \f2\lang1033\fs22 , vgl. RH 13430; (608) >\plain \f2\i\lang1033\fs22 Joannis Apostoli et evangeliste\plain \f2\lang1033\fs22 <. \plain \f2\i\lang1033\fs22 Amore Christi nobilis\plain \f2\lang1033\fs22  AH Bd. 50, Nr. 9; (609) >\plain \f2\i\lang1033\fs22 Divisio\plain \f2\lang1033\fs22 <. \plain \f2\i\lang1033\fs22 In principio erat verbum\plain \f2\lang1033\fs22 , vgl. RH 8736; (610) >\plain \f2\i\lang1033\fs22 Agnetis virginis et martyris\plain \f2\lang1033\fs22 <. \plain \f2\i\lang1033\fs22 Agnes beate virginis\plain \f2\lang1033\fs22  AH Bd. 50, Nr. 11; (611) >\plain \f2\i\lang1033\fs22 Divisio\plain \f2\lang1033\fs22 <. \plain \f2\i\lang1033\fs22 Aras nefandi numinis\plain \f2\lang1033\fs22 , vgl. RH 1261; (612) >\plain \f2\i\lang1033\fs22 In omnibus solemnitatibus sancte Marie\plain \f2\lang1033\fs22 <. \plain \f2\i\lang1033\fs22 Mysterium ecclesie hymnum \plain \f2\lang1033\fs22 AH Bd. 51, Nr. 121; (613) >\plain \f2\i\lang1033\fs22 Divisio\plain \f2\lang1033\fs22 <. \plain \f2\i\lang1033\fs22 Vere gratia plena es\plain \f2\lang1033\fs22  RH 21408; (614) >\plain \f2\i\lang1033\fs22 Ad completorium eisdem diebus\plain \f2\lang1033\fs22 <. \plain \f2\i\lang1033\fs22 Ave maris stella\plain \f2\lang1033\fs22  AH Bd. 51, Nr. 123; Bd. 2, S. 39, Nr. 29; (616) >\plain \f2\i\lang1033\fs22 Ad tertiam eodem tempore\plain \f2\lang1033\fs22 <. \plain \f2\i\lang1033\fs22 O quam glorifica luce choruscas\plain \f2\lang1033\fs22  AH Bd. 2, Nr. 30; (617) >\plain \f2\i\lang1033\fs22 Agathe virginis et martyris\plain \f2\lang1033\fs22 <. \plain \f2\i\lang1033\fs22 Agathe sacre virginis\plain \f2\lang1033\fs22  AH Bd. 51, Nr. 135; (618) >\plain \f2\i\lang1033\fs22 Divisio\plain \f2\lang1033\fs22 <. \plain \f2\i\lang1033\fs22 Sisti iubet martyrem\plain \f2\lang1033\fs22  RH 19038; (619) >\plain \f2\i\lang1033\fs22 In natali sancti Benedicti abbatis\plain \f2\lang1033\fs22 <. \plain \f2\i\lang1033\fs22 Beata nobis gaudia\plain \f2\lang1033\fs22  AH Bd. 4, Nr. 196; >\plain \f2\i\lang1033\fs22 Divisio\plain \f2\lang1033\fs22 <. \plain \f2\i\lang1033\fs22 De hinc virtute proficit\plain \f2\lang1033\fs22 , Textabbruch aufgrund von Blattverlust, vgl. Ms. D 33 fol. 400r\u8722 -v; (623) >\plain \f2\i\lang1033\fs22 Eodem tempore preter\u8230 \'85\endash \u8230 \'85 festa sanctorum ad tertiam\plain \f2\lang1033\fs22 <. \plain \f2\i\lang1033\fs22 Audi benigne conditor\plain \f2\lang1033\fs22  AH Bd. 51, Nr. 54; (624) >\plain \f2\i\lang1033\fs22 Dominica in passione domini usque in vigiliam pasche preter festa sanctorum et dominicam palmarum\plain \f2\lang1033\fs22 <. \plain \f2\i\lang1033\fs22 Hymnum dicamus domino\plain \f2\lang1033\fs22  AH Bd. 51, Nr. 75; (625) >\plain \f2\i\lang1033\fs22 Divisio\plain \f2\lang1033\fs22 <. \plain \f2\i\lang1033\fs22 Denariorum numero Christus\plain \f2\lang1033\fs22  RH 4351; (626) >\plain \f2\i\lang1033\fs22 Ad completorium usque in vigiliam pasche exceptis festis sanctorum\plain \f2\lang1033\fs22 <. \plain \f2\i\lang1033\fs22 Crux fidelis inter omnes\plain \f2\lang1033\fs22 , vgl. AH Bd. 50, Nr. 66, Str. 8\endash 10; >\plain \f2\i\lang1033\fs22 Ad tertiam usque in diem palmarum exceptis festis sanctorum\plain \f2\lang1033\fs22 <. \plain \f2\i\lang1033\fs22 Vexilla regis prodeunt fulget\plain \f2\lang1033\fs22  (628) AH Bd. 12, Nr. 493; (630) >\plain \f2\i\lang1033\fs22 In die palmarum\plain \f2\lang1033\fs22 <. \plain \f2\i\lang1033\fs22 Magnum salutis gaudium \plain \f2\lang1033\fs22 AH Bd. 51, Nr. 74; (631) >\plain \f2\i\lang1033\fs22 Divisio\plain \f2\lang1033\fs22 <. \plain \f2\i\lang1033\fs22 Ramos virentes sumpserat\plain \f2\lang1033\fs22 , vgl. RH 17005; (633) >\plain \f2\i\lang1033\fs22 Eodem die et per totam sequentem septimanam ad tertiam\plain \f2\lang1033\fs22 <. \plain \f2\i\lang1033\fs22 Iam surgit hora tertia\plain \f2\lang1033\fs22  AH Bd. 50, Nr. 6; (635) >\plain \f2\i\lang1033\fs22 In natali sancti Andree apostoli\plain \f2\lang1033\fs22 <. \plain \f2\i\lang1033\fs22 Post Petrum primum principem\plain \f2\lang1033\fs22  AH Bd. 51, Nr. 139; (636) >\plain \f2\i\lang1033\fs22 Divisio\plain \f2\lang1033\fs22 <. \plain \f2\i\lang1033\fs22 Fallax ad patibulum\plain \f2\lang1033\fs22 , vgl. RH 5951; (637) >\plain \f2\i\lang1033\fs22 De apostolis et martyribus\plain \f2\lang1033\fs22 <. \plain \f2\i\lang1033\fs22 Eterna Christi munera\plain \f2\lang1033\fs22  AH Bd. 50, Nr. 17; (638) >\plain \f2\i\lang1033\fs22 Divisio\plain \f2\lang1033\fs22 <. \plain \f2\i\lang1033\fs22 Traduntur igni martyres\plain \f2\lang1033\fs22 , vgl. RH 20529; (639) >\plain \f2\i\lang1033\fs22 De uno martyre\plain \f2\lang1033\fs22 <. \plain \f2\i\lang1033\fs22 Deus tuorum militum\plain \f2\lang1033\fs22  AH Bd. 51, Nr. 114b; (640) >\plain \f2\i\lang1033\fs22 Divisio\plain \f2\lang1033\fs22 <. \plain \f2\i\lang1033\fs22 Penas cucurrit fortiter\plain \f2\lang1033\fs22 , vgl. RH 15118; (641) >\plain \f2\i\lang1033\fs22 De confessoribus\plain \f2\lang1033\fs22 <. \plain \f2\i\lang1033\fs22 Jhesu corona celsior\plain \f2\lang1033\fs22  AH Bd. 51, Nr. 116; (642) >\plain \f2\i\lang1033\fs22 Divisio\plain \f2\lang1033\fs22 <. \plain \f2\i\lang1033\fs22 Te Christe rex piissime\plain \f2\lang1033\fs22 , vgl. RH 20043; (643) >\plain \f2\i\lang1033\fs22 De virginibus\plain \f2\lang1033\fs22 <. \plain \f2\i\lang1033\fs22 Jhesu corona virginum\plain \f2\lang1033\fs22  AH Bd. 50, Nr. 21; >\plain \f2\i\lang1033\fs22 Divisio\plain \f2\lang1033\fs22 <. \plain \f2\i\lang1033\fs22 Quocumque pergis virgines\plain \f2\lang1033\fs22 , vgl. RH 16876.}

