\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f2\scaps\lang1033\fs22\chcbpat17 Proprium de tempore}}\plain \f2\i\lang1033\fs24  >\plain \f2\i\lang1033\fs22 Dominica prima in adventu domini. Ad vesperas\plain \f2\lang1033\fs22 <, Magnificat-Antiphon \plain \f2\i\lang1033\fs22 Ecce nomen domini\plain \f2\lang1033\fs22  CAO \plain \f2\caps\lang1033\fs22 2527;\plain \f2\lang1033\fs22  weiter mit Invitatorium, Antiphon mit Psalminitium der ersten Nokturn sowie Responsorium \plain \f2\i\lang1033\fs22 Aspiciens a longe\plain \f2\lang1033\fs22  CAO 6129; Text inkl. Versikel \plain \f2\i\lang1033\fs22 Quique terrigene et filii hominum\plain \f2\lang1033\fs22 , vgl. Guerrini Nr. 14\endash 15. 
