\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs22\chcbpat17 Hymnar.}}\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 Hymnen aus dem Commune sanctorum zu Ehren der Apostel, zur Vesper und Matutin.\plain \f1\i\lang1033\fs24  >\plain \f1\i\lang1033\fs22 In festo apostolorum et evangelistarum. Ad vesperas et ad matutinas\plain \f1\lang1033\fs22 <. \plain \f1\i\lang1033\fs22 Exultet celum laudibus \plain \f1\lang1033\fs22 AH Bd. 2, Nr. 94; zu den Laudes \plain \f1\i\lang1033\fs22 Eterna Christi munera \plain \f1\lang1033\fs22 AH Bd. 50, Nr. 17; >\plain \f1\i\lang1033\fs22 In festo unius martiris. Ad vesperas et ad matutinas\plain \f1\lang1033\fs22 <. \plain \f1\i\lang1033\fs22 Deus tuorum militum \plain \f1\lang1033\fs22 AH Bd. 51, Nr. 114b; Laudes \plain \f1\i\lang1033\fs22 Martyr dei qui unicum \plain \f1\lang1033\fs22 AH Bd. 51, Nr. 113, Str. 1, V. 1\endash 2.}

